import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import {
  ImageIcon,
  Upload,
  Trash2,
  Edit2,
  ChevronUp,
  ChevronDown,
  Loader,
  X,
  Plus,
} from 'lucide-react';
import api from '../../services/api';
import Swal from 'sweetalert2';

const ServiceGalleryManager = () => {
  const [galleries, setGalleries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [formData, setFormData] = useState({
    service_id: 'quality',
    service_name: 'GESTIÓN DE CALIDAD',
    description: '',
    order: 0,
  });
  const [editingId, setEditingId] = useState(null);

  const services = [
    { id: 'quality', name: 'GESTIÓN DE CALIDAD' },
    { id: 'safety', name: 'SEGURIDAD Y SALUD EN EL TRABAJO' },
    { id: 'environment', name: 'GESTIÓN AMBIENTAL' },
  ];

  const [uploadProgress, setUploadProgress] = useState(0);

  useEffect(() => {
    loadGalleries();
  }, []);

  const loadGalleries = async () => {
    try {
      setLoading(true);
      const response = await api.get('/services/public/all');
      setGalleries(response.data);
    } catch (error) {
      console.error('Error loading galleries:', error);
      Swal.fire('Error', 'Error al cargar galerías', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 10485760) {
        Swal.fire('Error', 'El archivo es muy grande (máx 10MB)', 'error');
        return;
      }
      setSelectedFile(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!selectedFile && !editingId) {
      Swal.fire('Error', 'Selecciona una imagen', 'error');
      return;
    }

    try {
      setLoading(true);

      if (editingId) {
        // Actualizar
        await api.put(`/services/${editingId}`, {
          service_id: formData.service_id,
          service_name: formData.service_name,
          description: formData.description,
          order: parseInt(formData.order),
        });

        Swal.fire('Éxito', 'Galería actualizada', 'success');
      } else {
        // Crear
        const uploadData = new FormData();
        uploadData.append('image', selectedFile);
        uploadData.append('service_id', formData.service_id);
        uploadData.append('service_name', formData.service_name);
        uploadData.append('description', formData.description);
        uploadData.append('order', parseInt(formData.order));

        await api.post('/services', uploadData, {
          headers: { 'Content-Type': 'multipart/form-data' },
          onUploadProgress: (progressEvent) => {
            const progress = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            setUploadProgress(progress);
          },
        });

        Swal.fire('Éxito', 'Galería creada correctamente', 'success');
      }

      handleCloseModal();
      loadGalleries();
    } catch (error) {
      console.error('Error:', error);
      Swal.fire('Error', error.response?.data?.detail || 'Error al guardar', 'error');
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  };

  const handleDelete = async (id) => {
    const result = await Swal.fire({
      title: '¿Eliminar imagen?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      confirmButtonText: 'Sí, eliminar',
    });

    if (result.isConfirmed) {
      try {
        await api.delete(`/services/${id}`);
        Swal.fire('Eliminada', 'Imagen eliminada correctamente', 'success');
        loadGalleries();
      } catch (error) {
        Swal.fire('Error', 'Error al eliminar', 'error');
      }
    }
  };

  const handleMoveUp = async (id, currentOrder) => {
    if (currentOrder === 0) return;

    try {
      const gallery = galleries.find(g => g._id === id);
      const previousGallery = galleries.find(
        g => g.service_id === gallery.service_id && g.order === currentOrder - 1
      );

      if (previousGallery) {
        await api.post('/services/reorder', {
          items: [
            { id, order: currentOrder - 1 },
            { id: previousGallery._id, order: currentOrder },
          ],
        });
        loadGalleries();
      }
    } catch (error) {
      console.error('Error:', error);
    }
  };

  const handleMoveDown = async (id, currentOrder) => {
    try {
      const gallery = galleries.find(g => g._id === id);
      const nextGallery = galleries.find(
        g => g.service_id === gallery.service_id && g.order === currentOrder + 1
      );

      if (nextGallery) {
        await api.post('/services/reorder', {
          items: [
            { id, order: currentOrder + 1 },
            { id: nextGallery._id, order: currentOrder },
          ],
        });
        loadGalleries();
      }
    } catch (error) {
      console.error('Error:', error);
    }
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setSelectedFile(null);
    setFormData({
      service_id: 'quality',
      service_name: 'GESTIÓN DE CALIDAD',
      description: '',
      order: 0,
    });
    setEditingId(null);
    setUploadProgress(0);
  };

  const handleEdit = (gallery) => {
    setEditingId(gallery._id);
    setFormData({
      service_id: gallery.service_id,
      service_name: gallery.service_name,
      description: gallery.description,
      order: gallery.order,
    });
    setShowModal(true);
  };

  if (loading && galleries.length === 0) {
    return (
      <div className="flex justify-center py-12">
        <Loader className="w-12 h-12 animate-spin text-green-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">
            🖼️ Galería de Servicios
          </h2>
          <p className="text-gray-600 mt-1">
            Administra las imágenes de tus servicios
          </p>
        </div>
        <Button
          onClick={() => setShowModal(true)}
          className="bg-green-600 hover:bg-green-700"
        >
          <Plus className="w-4 h-4 mr-2" />
          Agregar Imagen
        </Button>
      </div>

      {/* Modal */}
      <Dialog open={showModal} onOpenChange={handleCloseModal}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>
              {editingId ? 'Editar' : 'Agregar'} Imagen de Servicio
            </DialogTitle>
          </DialogHeader>

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Servicio */}
            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Servicio *
              </label>
              <Select
                value={formData.service_id}
                onValueChange={(value) => {
                  const service = services.find(s => s.id === value);
                  setFormData({
                    ...formData,
                    service_id: value,
                    service_name: service?.name || '',
                  });
                }}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {services.map(service => (
                    <SelectItem key={service.id} value={service.id}>
                      {service.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Imagen */}
            {!editingId && (
              <div>
                <label className="text-sm font-semibold text-gray-700 block mb-2">
                  Imagen *
                </label>
                <div className="border-2 border-dashed rounded-lg p-6 text-center cursor-pointer hover:bg-gray-50">
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleFileSelect}
                    className="hidden"
                    id="file-input"
                  />
                  <label htmlFor="file-input" className="cursor-pointer">
                    {selectedFile ? (
                      <div>
                        <ImageIcon className="w-8 h-8 mx-auto text-green-600 mb-2" />
                        <p className="font-semibold text-gray-900">
                          {selectedFile.name}
                        </p>
                        <p className="text-xs text-gray-500">
                          {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>
                    ) : (
                      <div>
                        <Upload className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                        <p className="font-semibold text-gray-900">
                          Selecciona una imagen
                        </p>
                        <p className="text-xs text-gray-500">
                          JPG, PNG o WEBP (máx 10MB)
                        </p>
                      </div>
                    )}
                  </label>
                </div>

                {uploadProgress > 0 && (
                  <div className="mt-2">
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-green-600 h-2 rounded-full"
                        style={{ width: `${uploadProgress}%` }}
                      />
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Descripción */}
            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Descripción
              </label>
              <Textarea
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                placeholder="Describe qué muestra la imagen..."
                rows={3}
              />
            </div>

            {/* Orden */}
            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Orden (posición en galería)
              </label>
              <Input
                type="number"
                min="0"
                value={formData.order}
                onChange={(e) =>
                  setFormData({ ...formData, order: e.target.value })
                }
              />
            </div>

            <DialogFooter className="gap-2">
              <Button type="button" variant="outline" onClick={handleCloseModal}>
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-green-600 hover:bg-green-700"
                disabled={loading || (!selectedFile && !editingId)}
              >
                {loading ? (
                  <>
                    <Loader className="w-4 h-4 mr-2 animate-spin" />
                    Guardando...
                  </>
                ) : (
                  'Guardar'
                )}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Galerías por Servicio */}
      <div className="space-y-6">
        {services.map(service => {
          const serviceGalleries = galleries.filter(
            g => g.service_id === service.id
          );

          return (
            <Card key={service.id}>
              <CardHeader>
                <CardTitle className="text-lg flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full bg-green-600" />
                  {service.name}
                  <span className="text-sm font-normal text-gray-600 ml-auto">
                    {serviceGalleries.length} imagen{serviceGalleries.length !== 1 ? 's' : ''}
                  </span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                {serviceGalleries.length === 0 ? (
                  <div className="text-center py-8 bg-gray-50 rounded-lg">
                    <ImageIcon className="w-12 h-12 mx-auto text-gray-300 mb-2" />
                    <p className="text-gray-600">No hay imágenes en esta galería</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {serviceGalleries.sort((a, b) => a.order - b.order).map((gallery, idx) => (
                      <div
                        key={gallery._id}
                        className="border rounded-lg overflow-hidden hover:shadow-lg transition-shadow"
                      >
                        <div className="aspect-square bg-gray-100 overflow-hidden">
                          <img
                            src={gallery.image_url}
                            alt={gallery.description}
                            className="w-full h-full object-cover"
                          />
                        </div>
                        <div className="p-3">
                          <p className="text-sm font-semibold text-gray-900 truncate">
                            {gallery.description || 'Sin descripción'}
                          </p>
                          <p className="text-xs text-gray-500 mb-2">
                            Posición: {gallery.order + 1}
                          </p>

                          <div className="flex gap-1">
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => handleMoveUp(gallery._id, gallery.order)}
                              disabled={gallery.order === 0}
                              className="text-gray-600 hover:text-gray-900"
                            >
                              <ChevronUp className="w-4 h-4" />
                            </Button>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() =>
                                handleMoveDown(
                                  gallery._id,
                                  gallery.order
                                )
                              }
                              disabled={
                                gallery.order ===
                                serviceGalleries.length - 1
                              }
                              className="text-gray-600 hover:text-gray-900"
                            >
                              <ChevronDown className="w-4 h-4" />
                            </Button>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => handleEdit(gallery)}
                              className="text-blue-600 hover:text-blue-900 ml-auto"
                            >
                              <Edit2 className="w-4 h-4" />
                            </Button>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => handleDelete(gallery._id)}
                              className="text-red-600 hover:text-red-900"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
};

export default ServiceGalleryManager;
